// Personalisierte Reaktivierungs-Nachricht
const items = $input.all();
const results = [];

const templates = [
  (d) => `Hallo ${d.first_name} 👋\n\nWir vermissen dich! Dein letzter Besuch bei ${d.salon_name} war vor ${d.days_since_visit} Tagen${d.last_service ? ' (' + d.last_service + ')' : ''}.\n\nWir haben diese Woche noch freie Termine${d.last_staff_name ? ' bei ' + d.last_staff_name : ''}. Sollen wir dir einen reservieren? 💇\n\nAntwort mit JA und wir melden uns! 😊`,
  (d) => `Hi ${d.first_name}!\n\nSchon ${d.days_since_visit} Tage seit deinem letzten Besuch bei uns 😱\n\nZeit für frischen Wind? ${d.last_staff_name ? d.last_staff_name + ' freut sich auf dich!' : 'Wir freuen uns auf dich!'}\n\nEinfach hier antworten für einen Termin 📅`,
  (d) => `Hallo ${d.first_name},\n\nlange nicht gesehen! Bei ${d.salon_name} haben wir gerade tolle neue Treatments im Angebot.\n\nLust auf einen Termin? Schreib uns einfach! 💇‍♀️\n\nDein Team von ${d.salon_name}`
];

for (const item of items) {
  const d = item.json;
  // Zufälliges Template wählen
  const template = templates[Math.floor(Math.random() * templates.length)];
  const message = template(d);

  results.push({
    json: {
      ...d,
      message,
      template_name: 'reactivation'
    }
  });
}

return results;
